// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FinanceVerification) predicate.FinanceVerification {
	return predicate.FinanceVerification(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FinanceVerification) predicate.FinanceVerification {
	return predicate.FinanceVerification(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FinanceVerification) predicate.FinanceVerification {
	return predicate.FinanceVerification(sql.NotPredicates(p))
}
